// noiseVectors mirrors tests/fixtures/noise_vectors.json. The fixture is
// SYNTHETIC and generated by tests/fixtures/generate_noise_vectors.py,
// which implements the algorithm of docs/protocol/noise.md findings
// PF-004..PF-008 independently of this package (Python, cryptography
// library + RFC 7748 ladder cross-check).
type noiseVectors struct {
	Meta struct {
		Generator string   `json:"generator"`
		Backend   string   `json:"backend"`
		Findings  []string `json:"findings"`
	} `json:"meta"`
	Inputs struct {
		ConnHeader          string `json:"conn_header"`
		ClientEphemeralPriv string `json:"client_ephemeral_priv"`
		ClientEphemeralPub  string `json:"client_ephemeral_pub"`
		ServerEphemeralPriv string `json:"server_ephemeral_priv"`
		ServerEphemeralPub  string `json:"server_ephemeral_pub"`
		ServerStaticPriv    string `json:"server_static_priv"`
		ServerStaticPub     string `json:"server_static_pub"`
		ClientNoisePriv     string `json:"client_noise_priv"`
		ClientNoisePub      string `json:"client_noise_pub"`
		ClientPayload       string `json:"client_payload"`
		ServerCertPayload   string `json:"server_cert_payload"`
	} `json:"inputs"`
	HashChain map[string]string `json:"hash_chain"`
	Mixes     []struct {
		Label    string `json:"label"`
		DHSecret string `json:"dh_secret"`
		Write    string `json:"write"`
		Read     string `json:"read"`
	} `json:"mixes"`
	HandshakeCiphertexts struct {
		ServerHelloStatic   ctVector `json:"server_hello_static"`
		ServerHelloPayload  ctVector `json:"server_hello_payload"`
		ClientFinishStatic  ctVector `json:"client_finish_static"`
		ClientFinishPayload ctVector `json:"client_finish_payload"`
	} `json:"handshake_ciphertexts"`
	FinalKeys struct {
		ClientWrite string `json:"client_write"`
		ClientRead  string `json:"client_read"`
	} `json:"final_keys"`
	TransportFrames []struct {
		Direction  string `json:"direction"`
		Key        string `json:"key"`
		Counter    int    `json:"counter"`
		Plaintext  string `json:"plaintext"`
		Nonce      string `json:"nonce"`
		Ciphertext string `json:"ciphertext"`
	} `json:"transport_frames"`
}

// ctVector is one ciphertext vector: nonce and sealed output, hex encoded.
type ctVector struct {
	Nonce      string `json:"nonce"`
	Ciphertext string `json:"ciphertext"`
}

// loadNoiseVectors reads the shared fixture relative to this package dir.
func loadNoiseVectors(t *testing.T) *noiseVectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "tests", "fixtures", "noise_vectors.json"))
	if err != nil {
		t.Fatalf("loading noise vectors fixture: %v", err)
	}
	var v noiseVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("parsing noise vectors fixture: %v", err)
	}
	return &v
}

// mustHex decodes a fixture hex string or fails the test.
func mustHex(t *testing.T, name, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("fixture %s: invalid hex: %v", name, err)
	}
	return b
}

// wantHex asserts got equals the hex fixture want, byte for byte, with a
// diff on failure.
func wantHex(t *testing.T, name string, got []byte, want string) {
	t.Helper()
	wantBytes := mustHex(t, name, want)
	if !bytes.Equal(got, wantBytes) {
		t.Fatalf("%s: byte mismatch against fixture (PF-004..PF-008 vector)\n got  %x\n want %s", name, got, want)
	}
}

// findMix returns the mix entry with the given label.
func findMix(t *testing.T, v *noiseVectors, label string) (dh, write, read string) {
	t.Helper()
	for _, m := range v.Mixes {
		if m.Label == label {
			return m.DHSecret, m.Write, m.Read
		}
	}
	t.Fatalf("fixture: mix %q not found", label)
	return "", "", ""
}

// assertMix mixes dhSecretHex into h and asserts the resulting salt and
// counter against the fixture entry with the same label (PF-006). The
// fixture dh value is cross-checked against the Go-computed X25519 output.
func assertMix(t *testing.T, v *noiseVectors, h *Handshake, label, dhSecretHex string) {
	t.Helper()
	dh, wantWrite, _ := findMix(t, v, label)
	if dh != dhSecretHex {
		t.Fatalf("mix %s: fixture dh_secret %s does not match computed X25519 %s", label, dh, dhSecretHex)
	}
	if err := h.MixIntoKey(mustHex(t, label, dhSecretHex)); err != nil {
		t.Fatalf("mix %s: MixIntoKey: %v", label, err)
	}
	if h.counter != 0 {
		t.Fatalf("mix %s: counter must reset to 0, got %d", label, h.counter)
	}
	wantHex(t, "mix "+label+" salt", h.salt[:], wantWrite)
}

// TestNoiseProtocolNameRaw pins PF-004's trickiest constant: h0 is the
// zero-padded protocol name used RAW, not re-hashed — the chain root is
// the raw pattern, so Start(header) yields exactly one hash application
// over it.
func TestNoiseProtocolNameRaw(t *testing.T) {
	if len(noiseProtocolName) != 32 {
		t.Fatalf("protocol name must be 32 bytes, got %d", len(noiseProtocolName))
	}
	if !bytes.HasSuffix(noiseProtocolName, []byte{0, 0, 0, 0}) {
		t.Fatalf("protocol name must end with four NUL bytes: %x", noiseProtocolName)
	}
	if !bytes.HasPrefix(noiseProtocolName, []byte("Noise_XX_25519_AESGCM_SHA256")) {
		t.Fatalf("unexpected protocol name prefix: %x", noiseProtocolName)
	}
	var h0 [32]byte
	copy(h0[:], noiseProtocolName)

	header := []byte{0x57, 0x41, 0x06, 0x03} // transport.IntroHeader bytes (PF-004)
	h := NewHandshake()
	h.Start(header)
	chain := append([]byte{}, h0[:]...)
	chain = append(chain, header...)
	want := sha256.Sum256(chain)
	if h.hash != want {
		t.Fatalf("hash after Start must be SHA256(raw h0 || header) = %x, got %x", want, h.hash)
	}
	if h.salt != h0 {
		t.Fatalf("initial salt must be h0, got %x", h.salt)
	}
	if h.counter != 0 {
		t.Fatalf("initial counter must be 0, got %d", h.counter)
	}
	if h.key == nil {
		t.Fatal("initial handshake AEAD key must be created from h0")
	}
}

// TestVectorClientRole replays the full client role (PF-007 order) with
// the fixture's deterministic keys and asserts every intermediate value —
// hash chain entries, key schedule, counters, all four handshake
// ciphertexts and the final transport keys — byte for byte.
func TestVectorClientRole(t *testing.T) {
	v := loadNoiseVectors(t)
	in := v.Inputs

	clientEphPriv := mustHex(t, "client_ephemeral_priv", in.ClientEphemeralPriv)
	clientEphPub := mustHex(t, "client_ephemeral_pub", in.ClientEphemeralPub)
	serverEphPub := mustHex(t, "server_ephemeral_pub", in.ServerEphemeralPub)
	serverStaticPub := mustHex(t, "server_static_pub", in.ServerStaticPub)
	clientNoisePriv := mustHex(t, "client_noise_priv", in.ClientNoisePriv)
	clientNoisePub := mustHex(t, "client_noise_pub", in.ClientNoisePub)

	var clientEph, serverEph, serverStatic, clientNoise KeyPair // only the used halves are filled
	copy(clientEph.Priv[:], clientEphPriv)
	copy(clientEph.Pub[:], clientEphPub)
	copy(serverEph.Pub[:], serverEphPub)
	copy(serverStatic.Pub[:], serverStaticPub)
	copy(clientNoise.Priv[:], clientNoisePriv)
	copy(clientNoise.Pub[:], clientNoisePub)

	h := NewHandshake()
	h.Start(mustHex(t, "conn_header", in.ConnHeader))
	wantHex(t, "hash after conn header", h.hash[:], v.HashChain["after_conn_header"])

	// msg1: clientHello.ephemeral is plaintext, but the ephemeral joins
	// the hash chain before the frame is sent (PF-004).
	h.Authenticate(clientEph.Pub[:])
	wantHex(t, "hash after client ephemeral", h.hash[:], v.HashChain["after_client_ephemeral"])

	// msg2: serverHello (PF-007).
	h.Authenticate(serverEph.Pub[:])
	wantHex(t, "hash after server ephemeral", h.hash[:], v.HashChain["client_after_server_ephemeral"])
	goDH, err := curve25519.X25519(clientEph.Priv[:], serverEph.Pub[:])
	if err != nil {
		t.Fatalf("x25519 ee: %v", err)
	}
	assertMix(t, v, h, "client_ee", hex.EncodeToString(goDH))

	serverStaticPlain, err := h.Decrypt(mustHex(t, "server_hello_static.ct", v.HandshakeCiphertexts.ServerHelloStatic.Ciphertext))
	if err != nil {
		t.Fatalf("decrypt serverHello.static: %v", err)
	}
	if h.counter != 1 {
		t.Fatalf("counter after first decrypt must be 1, got %d", h.counter)
	}
	if !bytes.Equal(serverStaticPlain, serverStatic.Pub[:]) {
		t.Fatalf("decrypted server static mismatch: %x", serverStaticPlain)
	}
	wantHex(t, "hash after server static ciphertext", h.hash[:], v.HashChain["client_after_server_static_ciphertext"])

	goDH, err = curve25519.X25519(clientEph.Priv[:], serverStatic.Pub[:])
	if err != nil {
		t.Fatalf("x25519 es: %v", err)
	}
	assertMix(t, v, h, "client_es", hex.EncodeToString(goDH))

	certPlain, err := h.Decrypt(mustHex(t, "server_hello_payload.ct", v.HandshakeCiphertexts.ServerHelloPayload.Ciphertext))
	if err != nil {
		t.Fatalf("decrypt serverHello.payload: %v", err)
	}
	if !bytes.Equal(certPlain, mustHex(t, "server_cert_payload", in.ServerCertPayload)) {
		t.Fatalf("decrypted cert payload mismatch: %x", certPlain)
	}
	wantHex(t, "hash after server payload ciphertext", h.hash[:], v.HashChain["client_after_server_payload_ciphertext"])

	// msg3: clientFinish (PF-007) — the encrypt counter continues at 1
	// under the es key (shared encrypt/decrypt counter, PF-005).
	ctClientStatic, err := h.Encrypt(clientNoise.Pub[:])
	if err != nil {
		t.Fatalf("encrypt client static: %v", err)
	}
	wantHex(t, "clientFinish.static ciphertext", ctClientStatic, v.HandshakeCiphertexts.ClientFinishStatic.Ciphertext)
	wantHex(t, "clientFinish.static nonce", handshakeIV(1), v.HandshakeCiphertexts.ClientFinishStatic.Nonce)
	wantHex(t, "hash after client static ciphertext", h.hash[:], v.HashChain["after_client_static_ciphertext"])
	if h.counter != 2 {
		t.Fatalf("counter after client static encrypt must be 2, got %d", h.counter)
	}

	goDH, err = curve25519.X25519(clientNoise.Priv[:], serverEph.Pub[:])
	if err != nil {
		t.Fatalf("x25519 se: %v", err)
	}
	assertMix(t, v, h, "se", hex.EncodeToString(goDH))

	ctClientPayload, err := h.Encrypt(mustHex(t, "client_payload", in.ClientPayload))
	if err != nil {
		t.Fatalf("encrypt client payload: %v", err)
	}
	wantHex(t, "clientFinish.payload ciphertext", ctClientPayload, v.HandshakeCiphertexts.ClientFinishPayload.Ciphertext)
	wantHex(t, "clientFinish.payload nonce", handshakeIV(0), v.HandshakeCiphertexts.ClientFinishPayload.Nonce)
	wantHex(t, "hash after client payload ciphertext", h.hash[:], v.HashChain["after_client_payload_ciphertext"])

	writeKey, readKey, err := h.Finish()
	if err != nil {
		t.Fatalf("Finish: %v", err)
	}
	wantHex(t, "final client write key", writeKey[:], v.FinalKeys.ClientWrite)
	wantHex(t, "final client read key", readKey[:], v.FinalKeys.ClientRead)
}

// TestVectorServerRole replays the server role (PF-007 order) with the
// fixture's deterministic keys and asserts the same classes of values as
// TestVectorClientRole, proving both roles agree on the state machine.
func TestVectorServerRole(t *testing.T) {
	v := loadNoiseVectors(t)
	in := v.Inputs

	clientEphPub := mustHex(t, "client_ephemeral_pub", in.ClientEphemeralPub)
	serverEphPriv := mustHex(t, "server_ephemeral_priv", in.ServerEphemeralPriv)
	serverEphPub := mustHex(t, "server_ephemeral_pub", in.ServerEphemeralPub)
	serverStaticPriv := mustHex(t, "server_static_priv", in.ServerStaticPriv)
	serverStaticPub := mustHex(t, "server_static_pub", in.ServerStaticPub)
	clientNoisePub := mustHex(t, "client_noise_pub", in.ClientNoisePub)

	var serverEph, serverStatic KeyPair
	copy(serverEph.Priv[:], serverEphPriv)
	copy(serverEph.Pub[:], serverEphPub)
	copy(serverStatic.Priv[:], serverStaticPriv)
	copy(serverStatic.Pub[:], serverStaticPub)

	h := NewHandshake()
	h.Start(mustHex(t, "conn_header", in.ConnHeader))
	wantHex(t, "server hash after conn header", h.hash[:], v.HashChain["server_after_conn_header"])
	h.Authenticate(clientEphPub)
	wantHex(t, "server hash after client ephemeral", h.hash[:], v.HashChain["server_after_client_ephemeral"])

	// The server authenticates its own ephemeral before the first AEAD
	// operation so both roles share the identical chain (PF-004).
	h.Authenticate(serverEph.Pub[:])
	wantHex(t, "server hash after server ephemeral", h.hash[:], v.HashChain["after_server_ephemeral"])

	goDH, err := curve25519.X25519(serverEph.Priv[:], clientEphPub)
	if err != nil {
		t.Fatalf("x25519 ee: %v", err)
	}
	assertMix(t, v, h, "ee", hex.EncodeToString(goDH))

	ctServerStatic, err := h.Encrypt(serverStatic.Pub[:])
	if err != nil {
		t.Fatalf("encrypt server static: %v", err)
	}
	wantHex(t, "serverHello.static ciphertext", ctServerStatic, v.HandshakeCiphertexts.ServerHelloStatic.Ciphertext)
	wantHex(t, "serverHello.static nonce", handshakeIV(0), v.HandshakeCiphertexts.ServerHelloStatic.Nonce)
	wantHex(t, "server hash after server static ciphertext", h.hash[:], v.HashChain["after_server_static_ciphertext"])

	goDH, err = curve25519.X25519(serverStatic.Priv[:], clientEphPub)
	if err != nil {
		t.Fatalf("x25519 es: %v", err)
	}
	assertMix(t, v, h, "es", hex.EncodeToString(goDH))

	ctCert, err := h.Encrypt(mustHex(t, "server_cert_payload", in.ServerCertPayload))
	if err != nil {
		t.Fatalf("encrypt server payload: %v", err)
	}
	wantHex(t, "serverHello.payload ciphertext", ctCert, v.HandshakeCiphertexts.ServerHelloPayload.Ciphertext)
	wantHex(t, "serverHello.payload nonce", handshakeIV(0), v.HandshakeCiphertexts.ServerHelloPayload.Nonce)
	wantHex(t, "server hash after server payload ciphertext", h.hash[:], v.HashChain["after_server_payload_ciphertext"])

	clientStaticPlain, err := h.Decrypt(mustHex(t, "client_finish_static.ct", v.HandshakeCiphertexts.ClientFinishStatic.Ciphertext))
	if err != nil {
		t.Fatalf("decrypt clientFinish.static: %v", err)
	}
	if !bytes.Equal(clientStaticPlain, clientNoisePub) {
		t.Fatalf("decrypted client static mismatch: %x", clientStaticPlain)
	}
	wantHex(t, "server hash after client static ciphertext", h.hash[:], v.HashChain["after_client_static_ciphertext"])

	goDH, err = curve25519.X25519(serverEph.Priv[:], clientStaticPlain)
	if err != nil {
		t.Fatalf("x25519 se: %v", err)
	}
	assertMix(t, v, h, "server_se", hex.EncodeToString(goDH))

	clientPayloadPlain, err := h.Decrypt(mustHex(t, "client_finish_payload.ct", v.HandshakeCiphertexts.ClientFinishPayload.Ciphertext))
	if err != nil {
		t.Fatalf("decrypt clientFinish.payload: %v", err)
	}
	if !bytes.Equal(clientPayloadPlain, mustHex(t, "client_payload", in.ClientPayload)) {
		t.Fatalf("decrypted client payload mismatch: %x", clientPayloadPlain)
	}
	wantHex(t, "server hash after client payload ciphertext", h.hash[:], v.HashChain["after_client_payload_ciphertext"])

	rawWrite, rawRead, err := h.Finish()
	if err != nil {
		t.Fatalf("Finish: %v", err)
	}
	// Both roles compute identical HKDF halves (PF-008); the server USES
	// them swapped, which the round-trip test exercises.
	wantHex(t, "server raw write half", rawWrite[:], v.FinalKeys.ClientWrite)
	wantHex(t, "server raw read half", rawRead[:], v.FinalKeys.ClientRead)
}

// TestVectorMixRolesAgree asserts the server-side and client-side mix
// entries in the fixture are identical, i.e. both simulated roles derive
// the same key schedule (PF-006).
func TestVectorMixRolesAgree(t *testing.T) {
	v := loadNoiseVectors(t)
	for _, pair := range [][2]string{
		{"ee", "client_ee"},
		{"es", "client_es"},
		{"se", "server_se"},
	} {
		dhS, writeS, readS := findMix(t, v, pair[0])
		dhC, writeC, readC := findMix(t, v, pair[1])
		if dhS != dhC || writeS != writeC || readS != readC {
			t.Fatalf("mix %s/%s disagree: dh %s/%s write %s/%s read %s/%s",
				pair[0], pair[1], dhS, dhC, writeS, writeC, readS, readC)
		}
	}
}

// TestVectorTransportFrames asserts post-handshake frame encryption
// (PF-008): empty AAD, counter IV, per-direction keys — byte for byte
// against the fixture, in both directions.
func TestVectorTransportFrames(t *testing.T) {
	v := loadNoiseVectors(t)
	ctx := context.Background()
	for _, f := range v.TransportFrames {
		t.Run(f.Direction, func(t *testing.T) {
			var keyHex string
			switch f.Key {
			case "client_write":
				keyHex = v.FinalKeys.ClientWrite
			case "client_read":
				keyHex = v.FinalKeys.ClientRead
			default:
				t.Fatalf("fixture: unknown key role %q", f.Key)
			}
			key := [32]byte{}
			copy(key[:], mustHex(t, "key "+f.Key, keyHex))
			plaintext := mustHex(t, "plaintext", f.Plaintext)

			// Writing direction.
			rec := &recorderConn{}
			sc, err := newSecureConn(rec, key, key)
			if err != nil {
				t.Fatalf("newSecureConn: %v", err)
			}
			if err := sc.WriteFrame(ctx, plaintext); err != nil {
				t.Fatalf("WriteFrame: %v", err)
			}
			if len(rec.frames) != 1 {
				t.Fatalf("expected 1 recorded frame, got %d", len(rec.frames))
			}
			wantHex(t, "transport frame ciphertext", rec.frames[0], f.Ciphertext)
			if sc.writeCounter != uint32(f.Counter)+1 {
				t.Fatalf("write counter must be %d after one frame, got %d", f.Counter+1, sc.writeCounter)
			}

			// Reading direction: feed the recorded ciphertext back and
			// expect the plaintext.
			rec2 := &recorderConn{frames: [][]byte{append([]byte(nil), rec.frames[0]...)}}
			sc2, err := newSecureConn(rec2, key, key)
			if err != nil {
				t.Fatalf("newSecureConn: %v", err)
			}
			got, err := sc2.ReadFrame(ctx)
			if err != nil {
				t.Fatalf("ReadFrame: %v", err)
			}
			if !bytes.Equal(got, plaintext) {
				t.Fatalf("round-tripped plaintext mismatch: %x", got)
			}
		})
	}
}
